function fail(message) {
  console.error(`\nMVP Studio V2 Phase 2 installer stopped: ${message}\n`);
  process.exit(1);
}
function ensureParent(file) { fs.mkdirSync(path.dirname(file), { recursive: true }); }
const eolByFile = new Map();
function readNormalized(file) {
  if (!fs.existsSync(file)) fail(`Missing ${path.relative(root, file)}.`);
  const raw = fs.readFileSync(file, "utf8");
  eolByFile.set(file, raw.includes("\r\n") ? "\r\n" : "\n");
  return raw.replace(/\r\n/g, "\n");
}
function writeText(file, content) {
  ensureParent(file);
  const eol = eolByFile.get(file) || "\n";
  fs.writeFileSync(file, eol === "\r\n" ? content.replace(/\n/g, "\r\n") : content);
}
function backup(file) {
  if (!fs.existsSync(file)) return;
  const target = `${file}.pre-studio-v2-phase2-multiband.bak`;
  if (!fs.existsSync(target)) fs.copyFileSync(file, target);
}
function replaceOnce(source, search, replacement, label) {
  const first = source.indexOf(search);
  if (first < 0) fail(`Could not find ${label}. Make sure Studio V2 Transient is installed and live first.`);
  if (source.indexOf(search, first + search.length) >= 0) fail(`${label} matched more than once; refusing an ambiguous patch.`);
  return source.slice(0, first) + replacement + source.slice(first + search.length);
}
function insertBeforeOnce(source, anchor, insertion, label) {
  const first = source.indexOf(anchor);
  if (first < 0) fail(`Could not find ${label}.`);
  if (source.indexOf(anchor, first + anchor.length) >= 0) fail(`${label} matched more than once; refusing an ambiguous patch.`);
  return source.slice(0, first) + insertion + source.slice(first);
}

